use std::io::{self, Read};

fn best(v: &Vec<(String, i64)>) -> Option<usize> {
    let mut b: Option<usize> = None;
    for (i, e) in v.iter().enumerate() {
        match b {
            None => b = Some(i),
            Some(j) => {
                if e.1 > v[j].1 {
                    b = Some(i);
                }
            }
        }
    }
    b
}

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut q: Vec<(String, i64)> = Vec::new();
    let mut out = String::new();
    for line in s.lines() {
        let p: Vec<&str> = line.split_whitespace().collect();
        match p.as_slice() {
            ["add", n, pr] => match pr.parse::<i64>() {
                Ok(x) => q.push((n.to_string(), x)),
                Err(_) => out.push_str("error\n"),
            },
            ["pop"] => match best(&q) {
                Some(i) => {
                    let e = q.remove(i);
                    out.push_str(&format!("{}\n", e.0));
                }
                None => out.push_str("empty\n"),
            },
            ["peek"] => match best(&q) {
                Some(i) => out.push_str(&format!("{}\n", q[i].0)),
                None => out.push_str("empty\n"),
            },
            ["size"] => out.push_str(&format!("{}\n", q.len())),
            _ => out.push_str("error\n"),
        }
    }
    out.push_str("left:\n");
    while let Some(i) = best(&q) {
        let e = q.remove(i);
        out.push_str(&format!("{} {}\n", e.0, e.1));
    }
    print!("{}", out);
}

